SELECT * FROM PAYROLLS


        AND (staff_name ILIKE CONCAT('%', #{keyword}, '%')
        OR CAST(staff_id AS TEXT) LIKE CONCAT('%', #{keyword}, '%'))


        AND salary_period = #{salaryPeriod}


        AND status = #{status}


ORDER BY salary_period DESC, staff_name ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM PAYROLLS


        AND (staff_name ILIKE CONCAT('%', #{keyword}, '%')
        OR CAST(staff_id AS TEXT) LIKE CONCAT('%', #{keyword}, '%'))


        AND salary_period = #{salaryPeriod}


        AND status = #{status}

SELECT * FROM PAYROLLS
WHERE staff_id = #{staffId}
ORDER BY salary_period DESC
LIMIT #{limit} OFFSET #{offset}
